/*
 * MPU6050 Accelerometer — read X/Y/Z over I2C
 *
 * Wiring:
 *   VCC -> 5V
 *   GND -> GND
 *   SCL -> A5
 *   SDA -> A4
 *
 * Run the sketch, then drag the AccelX/Y/Z sliders on the
 * sensor component — the readings update live.
 */

#include <Wire.h>

const int MPU_ADDR = 0x68;

int accelX = 0;
int accelY = 0;
int accelZ = 0;

void setup() {
  Wire.begin();
  Serial.begin(115200);
  Serial.println("MPU6050 ready. Move the Accel sliders!");
}

void loop() {
  // Point the register pointer at ACCEL_XOUT_H (0x3B), then read 6 bytes
  Wire.beginTransmission(MPU_ADDR);
  Wire.write(0x3B);
  Wire.endTransmission(false);

  Wire.requestFrom(MPU_ADDR, 6);
  accelX = Wire.read() << 8 | Wire.read();
  accelY = Wire.read() << 8 | Wire.read();
  accelZ = Wire.read() << 8 | Wire.read();

  Serial.print("X: ");
  Serial.print(accelX);
  Serial.print("  Y: ");
  Serial.print(accelY);
  Serial.print("  Z: ");
  Serial.println(accelZ);

  delay(300);
}
